use vybe_compiler::primitives::{bundle,globals,platforms,strings};
use vybe_runtime::{Chunk,Op,VM,Value};
type Emit=fn(&mut [Chunk],usize,u32);
const EMIT:[Emit;6]=[strings::emit_is_digit,strings::emit_is_alpha,strings::emit_is_alnum,strings::emit_is_space,strings::emit_is_upper,strings::emit_is_lower];
fn program(class:usize,locals:u16)->Vec<Chunk>{let mut root=Chunk::new("classifier-controls");root.local_count=locals;globals::emit_read(&mut root,"text",17);let mut chunks=vec![root];EMIT[class](&mut chunks,0,17);chunks[0].emit_op(Op::RETURN,17);bundle::finalize_with_runtime_helpers(&mut chunks);globals::declare_free_globals(&mut chunks);globals::normalize_global_table(&mut chunks);chunks}
fn expected(class:usize,s:&str)->bool{match class{0=>!s.is_empty()&&s.chars().all(|c|c.is_ascii_digit()),1=>!s.is_empty()&&s.chars().all(char::is_alphabetic),2=>!s.is_empty()&&s.chars().all(|c|c.is_alphabetic()||c.is_ascii_digit()),3=>!s.is_empty()&&s.chars().all(char::is_whitespace),4=>s.chars().any(char::is_uppercase)&&!s.chars().any(char::is_lowercase),5=>s.chars().any(char::is_lowercase)&&!s.chars().any(char::is_uppercase),_=>unreachable!()}}
#[test]fn all_classes_ascii_unicode_repeated_varied_and_reset(){let mut texts:Vec<String>=(0..128).map(|cp|char::from_u32(cp).unwrap().to_string()).collect();texts.extend(["","ΩΩΩ","ΩAΩ","Ωμέγακόσμος","ΩΜΕΓΑΚΟΣΜΟΣ","ÉéÉ","ééé","ßß","中中","𐐀𐐀","𐐨𐐨","😀😀","Ω 😀","\u{a0}\u{a0}","\u{2003}\u{2003}","ABC123","abc123","A-a","e\u{301}","\u{10ffff}","123"].iter().map(|s|s.to_string()));for class in 0..6{let chunks=program(class,0);let native=vybe_platform_wasm::write_wasm(&chunks);wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all()).validate_all(&native).unwrap();eprintln!("class={class} bytes={} locals={} native={}",chunks[0].code.len(),chunks[0].local_count,native.len());let mut vm=VM::new();platforms::register_platforms_all(&mut vm);for s in &texts{vm.set_global("text",Value::String(s.clone().into()));assert_eq!(vm.run(chunks.clone()).unwrap(),Value::Bool(expected(class,s)),"class={class} text={s:?}");assert!(vm.last_exception.is_none());}}}
#[test]fn reduced_local_budget_at_native_and_vm_limits(){for(class,delta)in[(0,5),(1,9),(4,13)]{for initial in [49900,u16::MAX-delta]{let chunks=program(class,initial);assert_eq!(chunks[0].local_count,initial+delta);if initial==49900{wasmparser::Validator::new_with_features(wasmparser::WasmFeatures::all()).validate_all(&vybe_platform_wasm::write_wasm(&chunks)).unwrap();}let mut vm=VM::new();platforms::register_platforms_all(&mut vm);vm.set_global("text",Value::String(if class==0{"77"}else{"ΩΩ"}.into()));assert_eq!(vm.run(chunks).unwrap(),Value::Bool(true));}}}
#[test]fn nonstring_errors_keep_standard_string_length_contract(){for class in 0..6{for input in [Value::Null,Value::I32(3)]{let mut vm=VM::new();platforms::register_platforms_all(&mut vm);vm.set_global("text",input);let result=vm.run(program(class,0));assert!(result.is_err()||vm.last_exception.is_some(),"class={class}: nonstring must fail");}}}
